import NavbarCornerPanel from '@/components/tweenui/navbar-corner-panel';

export default function Layout({ children }: { children: React.ReactNode }) {
  return (
    <NavbarCornerPanel
      brand="Atelier"
      currentHref="/work"
      links={[
